$(function() {
    $('.backdatepicker').datepicker({
        dateFormat: 'dd/mm/yy',
        maxDate:0,
        changeMonth: true,
        changeYear: true,
        yearRange: "-100:+0"
    });

    $( ".backdatepicker" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" }).attr('autocomplete','off');
});




$( function() {
    var dateFormat = "dd/mm/yy",
        from = $( "#reportfrom" ).datepicker({
            changeMonth: true,
            changeYear: true,
            dateFormat:dateFormat,
            minDate:'-'+dateFromOpen+'d'
        })
            .on( "change", function() {
                to.datepicker( "option", "minDate", getDate( this ) );
            }),
        to = $( "#reportto" ).datepicker({
            changeMonth: true,
            changeYear: true,
            dateFormat:dateFormat,
            minDate:'-'+dateFromOpen+'d'
        });
// .on( "change", function() {
//         from.datepicker( "option", "maxDate", getDate( this ) );
//     })

    function getDate( element ) {
        var date;
        try {
            date = $.datepicker.parseDate( dateFormat, element.value );
        } catch( error ) {
            date = null;
        }
        return date;
    }
    $( "#reportfrom, #reportto" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" });
});